def fig_ton():
    X=lambda t:50+t*28
    def path(pts):return '<path d="M'+' L'.join(f'{X(t):.0f} {y}' for t,y in pts)+'" class="lna"/>'
    o=L(50,22,50,196)+L(50,196,330,196)
    o+=path([(0,60),(1,60),(1,30),(8,30),(8,60),(10,60)])+path([(0,120),(6,120),(6,90),(8,90),(8,120),(10,120)])+path([(0,190),(1,190),(6,150),(8,150),(8,190),(10,190)])
    for t in (1,6,8):o+=f'<line x1="{X(t)}" y1="22" x2="{X(t)}" y2="196" class="ln dash"/>'
    o+=TR(46,48,'IN','t-s t-b')+TR(46,108,'Q','t-s t-b')+TR(46,172,'ET','t-s t-b')
    for t in (0,1,6,8,10):o+=T(X(t),210,str(t),'t-s')
    o+=TL(X(1)+4,176,'PT = 5 с','t-s ac')+TL(250,224,'уақыт, с','t-s t-b')
    return S(340,232,o,'TON таймерінің уақыт диаграммасы')
f_ton=F(fig_ton(),'TON (PT = 5 с): IN 1-секундта қосылады, ET санай бастайды, 6-секундта (1 + 5) Q қосылады; IN өшсе, Q да, ET де бірден нөлге түседі')

